import {loadCatalog} from './data.js';
import {spotterPool,makeSpotter,answeredCount,remainingSeconds} from './spotter-logic.js';
const app=document.querySelector('#spotter-app');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let catalog,region='',minutes=0,run=[],position=0,deadline=null,view='setup',confirmSubmit=false,expired=false;
const button=(text,action,extra='')=>`<button class="secondary" data-action="${action}" ${extra}>${text}</button>`;
function picture(image,reveal=false){const src=reveal&&image.answerSrc?image.answerSrc:image.quizSrc;const marker=image.quizMarker;return `<div class="marked-image"><img src="./${esc(src)}" alt="${reveal?esc(image.alt):esc(image.quizAlt||'Identify the marked structure.')}">${marker&&!(reveal&&image.answerSrc)?`<span class="image-marker" style="left:${marker.x*100}%;top:${marker.y*100}%" aria-hidden="true">A</span>`:''}</div>`;}
function setup(){view='setup';const pool=spotterPool(catalog,region);const regions=[...new Set(catalog.structures.flatMap(s=>s.regions))].sort();app.innerHTML=`<section class="spotter"><div class="eyebrow">Beyond the lab</div><h1>Mock spotter</h1><p class="intro">30 images. 30 questions. Test identification, actions, innervation and more, then compare your responses with the shared answers.</p><p class="muted">An independent revision mock, using your selected timing—not an official Swansea assessment.</p><div class="spotter-settings"><label>Region<select id="exam-region"><option value="">All regions</option>${regions.map(r=>`<option ${region===r?'selected':''}>${esc(r)}</option>`).join('')}</select></label><label>Time for a full mock<select id="exam-time"><option value="0" ${!minutes?'selected':''}>Untimed</option><option value="30" ${minutes===30?'selected':''}>30 minutes</option><option value="45" ${minutes===45?'selected':''}>45 minutes</option></select></label></div><p class="exam-notice"><strong>${pool.length} structures ready.</strong> Each question uses a different structure with an unlabelled, marked image. Answers and structure names stay hidden until you submit.${pool.length<30?` Add ${30-pool.length} more to enable a full mock.`:''}</p><div class="spotter-bar">${button('Start 30-question mock','start',pool.length<30?'disabled':'')}${pool.length>0&&pool.length<30?button(`Practise ${pool.length} questions`,'practice'):''}</div>${!pool.length?'<p>Image questions will appear here as you add spotter-ready images. Knowledge revision is already available in the anatomy library.</p>':''}<a href="./library.html">Browse the anatomy library</a>${['127.0.0.1','localhost'].includes(location.hostname)?' · <a href="./manage-images">Add images</a>':''}<p class="muted">Responses stay in this tab only. Refreshing or leaving the page ends your run.</p></section>`;}
function clockText(){const n=remainingSeconds(deadline);return n===null?'Untimed':`${Math.floor(n/60)}:${String(n%60).padStart(2,'0')} remaining`;}
function paper(){const q=run[position];app.innerHTML=`<section class="spotter"><div class="spotter-bar"><strong>Question ${position+1} of ${run.length}</strong><time id="exam-clock">${clockText()}</time>${button('Submit exam','submit')}</div><progress max="${run.length}" value="${answeredCount(run)}" aria-label="Questions answered"></progress>${confirmSubmit?`<section class="exam-notice" role="alert"><p>${run.length-answeredCount(run)} unanswered. Submit now to finish and reveal all answers?</p>${button('Keep working','cancel-submit')} ${button('Submit and reveal answers','finish')}</section>`:''}<article class="spotter-paper">${picture(q.image)}<h2>${esc(q.question)}</h2><label for="exam-response">Your response</label><textarea id="exam-response" placeholder="Write your answer…">${esc(q.response)}</textarea><div class="spotter-bar">${button(q.flagged?'Flagged for review':'Flag for review','flag',`aria-pressed="${q.flagged}"`)}<span id="answered-summary">${answeredCount(run)} of ${run.length} answered</span></div></article><div class="spotter-bar">${button('← Previous','previous',position===0?'disabled':'')}${button(position===run.length-1?'Review & submit':'Next →',position===run.length-1?'submit':'next')}</div><nav class="question-jump" aria-label="Exam questions">${run.map((q,i)=>`<button data-action="jump" data-index="${i}" class="${q.response.trim()?'answered ':''}${q.flagged?'flagged':''}" aria-current="${i===position}" aria-label="Question ${i+1}${q.response.trim()?', answered':', unanswered'}${q.flagged?', flagged':''}">${i+1}</button>`).join('')}</nav><p class="muted">Blue: answered · Gold border: flagged. Answers are shown only after submission.</p></section>`;}
function review(){view='review';confirmSubmit=false;app.innerHTML=`<section class="spotter"><div class="eyebrow">${expired?'Time is up':'Run complete'}</div><h1>Review your spotter</h1><p>${answeredCount(run)} of ${run.length} questions answered. Compare your wording with the key, then mark each response.</p><p id="mark-summary" role="status"></p>${button('New mock','new')}${run.map((q,i)=>`<article class="spotter-review"><h2>${i+1}. ${esc(q.question)}</h2><details><summary>View image · ${esc(q.name)}</summary>${picture(q.image,true)}${q.image.credit?`<p class="muted">${esc(q.image.credit)}${q.image.license?' · '+esc(q.image.license):''}</p>`:''}</details><h3>Your response</h3><p>${esc(q.response.trim()||'No response')}</p><h3>Answer</h3><p>${esc(q.answer)}</p><a href="./library.html?structure=${encodeURIComponent(q.structureId)}" target="_blank" rel="noopener">Explore ${esc(q.name)}</a><div class="mark-controls">${button('Correct','correct',`data-index="${i}" aria-pressed="${q.mark===true}"`)}${button('Needs revision','incorrect',`data-index="${i}" aria-pressed="${q.mark===false}"`)}</div></article>`).join('')}<p class="muted">Self-marked practice only. Nothing is saved after this session.</p></section>`;markSummary();window.scrollTo(0,0);}
function markSummary(){const marked=run.filter(q=>q.mark!==null).length,correct=run.filter(q=>q.mark===true).length;document.querySelector('#mark-summary').textContent=`${correct} correct · ${marked} of ${run.length} reviewed${marked===run.length?` · ${Math.round(correct/run.length*100)}%`:''}`;}
app.addEventListener('input',e=>{if(e.target.id==='exam-response'){run[position].response=e.target.value;document.querySelector('#answered-summary').textContent=`${answeredCount(run)} of ${run.length} answered`;document.querySelector('progress').value=answeredCount(run);const b=app.querySelector(`[data-action="jump"][data-index="${position}"]`);b.classList.toggle('answered',!!e.target.value.trim());b.setAttribute('aria-label',`Question ${position+1}, ${e.target.value.trim()?'answered':'unanswered'}${run[position].flagged?', flagged':''}`);}});
app.addEventListener('change',e=>{if(e.target.id==='exam-region'){region=e.target.value;setup();}if(e.target.id==='exam-time')minutes=Number(e.target.value);});
app.addEventListener('click',e=>{const b=e.target.closest('button[data-action]');if(!b||b.disabled)return;const a=b.dataset.action;
 if(a==='start'||a==='practice'){const pool=spotterPool(catalog,region);run=makeSpotter(pool,a==='start'?30:pool.length);position=0;expired=false;confirmSubmit=false;deadline=minutes?Date.now()+minutes*60000*(run.length/30):null;view='exam';paper();window.scrollTo(0,0);return;}
 if(a==='new'){run=[];deadline=null;setup();window.scrollTo(0,0);return;}
 if(a==='correct'||a==='incorrect'){run[Number(b.dataset.index)].mark=a==='correct';b.parentElement.querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));markSummary();return;}
 if(view!=='exam')return;
 if(a==='finish'){review();return;}if(a==='submit')confirmSubmit=true;if(a==='cancel-submit')confirmSubmit=false;
 if(a==='flag')run[position].flagged=!run[position].flagged;
 if(a==='previous'&&position>0)position--;if(a==='next'&&position<run.length-1)position++;if(a==='jump')position=Number(b.dataset.index);paper();if(['previous','next','jump','submit'].includes(a))window.scrollTo(0,0);
});
app.addEventListener('error',e=>{if(e.target.tagName==='IMG'){e.target.hidden=true;const p=document.createElement('p');p.textContent='This image could not load. You can flag this question and continue.';p.setAttribute('role','status');e.target.parentElement.append(p);}},true);
setInterval(()=>{if(view!=='exam'||deadline===null)return;if(remainingSeconds(deadline)===0){expired=true;review();}else{const clock=document.querySelector('#exam-clock');if(clock)clock.textContent=clockText();}},500);
try{catalog=await loadCatalog();setup();}catch{app.innerHTML='<section class="spotter"><h1>The mock could not load</h1><p>Refresh the page to try again.</p></section>';}
